// ===== Helpers =====
fn effective_color(root: &ArgMatches, sub: Option<&ArgMatches>) -> String {
    use clap::parser::ValueSource;
    if let Some(s) = sub {
        if let Some(v) = s.value_source("color") {
            if v == ValueSource::CommandLine {
                if let Some(c) = s.get_one::<String>("color") {
                    return c.clone();
                }
            }
        }
        // also check nested? for config get etc, sub is the top sub (config), need to check nested
    }
    if let Some(v) = root.value_source("color") {
        if v == ValueSource::CommandLine {
            if let Some(c) = root.get_one::<String>("color") {
                return c.clone();
            }
        }
    }
    // if sub has default auto, use it (same as root default)
    if let Some(s) = sub {
        if let Some(c) = s.get_one::<String>("color") {
            return c.clone();
        }
    }
    if let Some(c) = root.get_one::<String>("color") {
        return c.clone();
    }
    "auto".to_string()
}

fn use_color(color_opt: &str) -> bool {
    match color_opt {
        "always" => true,
        "never" => false,
        _ => std::io::stdout().is_terminal(),
    }
}

