#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
struct RuleInfo {
    code: String,
    name: String,
    aliases: Vec<String>,
    summary: String,
    category: String,
    fix: String,
    fix_availability: String,
    url: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    explanation: Option<String>,
}

fn load_rules() -> Vec<RuleInfo> {
    let data = include_str!("../data/rules.json");
    serde_json::from_str(data).unwrap()
}

fn load_rules_explain() -> Vec<RuleInfo> {
    let data = include_str!("../data/rules_explain.json");
    serde_json::from_str(data).unwrap()
}

fn find_rule(code_or_name: &str) -> Option<RuleInfo> {
    // Only codes, case-insensitive (names not supported, per observed behavior)
    let upper = code_or_name.to_uppercase();
    let rules = load_rules();
    for r in rules {
        if r.code.to_uppercase() == upper {
            return Some(r);
        }
    }
    None
}

fn find_rule_explain(code: &str) -> Option<RuleInfo> {
    let upper = code.to_uppercase();
    let rules = load_rules_explain();
    for r in rules {
        if r.code.to_uppercase() == upper {
            return Some(r);
        }
    }
    None
}
