// ===== Config handling =====
#[derive(Debug, Clone)]
struct LoadedConfig {
    path: Option<PathBuf>,
    kind: String, // "default", "project config", "pyproject.toml", etc.
    toml_value: toml::Value,
}

fn find_config_file(explicit: Option<&str>) -> Result<Option<PathBuf>, String> {
    if let Some(p) = explicit {
        let pb = PathBuf::from(p);
        if !pb.exists() {
            return Err(format!("Failed to read config file at {}: No such file or directory (os error 2)", p));
        }
        return Ok(Some(pb));
    }
    // Search upwards from current dir for .rumdl.toml, rumdl.toml, pyproject.toml, .rumdl.toml etc?
    // Observed: prefers .rumdl.toml over rumdl.toml in same dir, and searches parents.
    // Also supports pyproject.toml with [tool.rumdl]
    let mut dir = std::env::current_dir().unwrap_or(PathBuf::from("."));
    loop {
        let c1 = dir.join(".rumdl.toml");
        if c1.exists() { return Ok(Some(c1)); }
        let c2 = dir.join("rumdl.toml");
        if c2.exists() { return Ok(Some(c2)); }
        // Also check .rumdl.toml? already. What about rumdl.toml.example? No.
        let c3 = dir.join("pyproject.toml");
        if c3.exists() {
            // Check if it has [tool.rumdl]
            if let Ok(content) = std::fs::read_to_string(&c3) {
                if content.contains("[tool.rumdl") {
                    return Ok(Some(c3));
                }
            }
        }
        if !dir.pop() { break; }
    }
    Ok(None)
}

fn load_config_file(path: &Path) -> Result<toml::Value, String> {
    let content = std::fs::read_to_string(path).map_err(|e| format!("Failed to read config file at {}: {}", path.display(), e))?;
    let v: toml::Value = content.parse::<toml::Value>().map_err(|e| format!("Failed to parse config: {}: Failed to parse TOML: {}", path.display(), e))?;
    // If pyproject.toml, extract [tool.rumdl]
    if path.file_name().map(|n| n == "pyproject.toml").unwrap_or(false) {
        if let Some(tool) = v.get("tool").and_then(|t| t.get("rumdl")) {
            return Ok(tool.clone());
        } else {
            return Ok(toml::Value::Table(toml::map::Map::new()));
        }
    }
    Ok(v)
}

// Default config values for display (from observed config_text)
fn default_config_toml() -> toml::Value {
    // Build minimal defaults for global + rule configs needed for display
    // We will hardcode the display logic instead of full struct
    toml::Value::Table(toml::map::Map::new())
}

fn main() {
    let cmd = build_cli();
    let matches = cmd.get_matches();
    let code = run(matches);
    std::process::exit(code);
}

fn run(matches: ArgMatches) -> i32 {
    let (sub_name, sub_matches) = match matches.subcommand() {
        Some((n, m)) => (n, m),
        None => return 2,
    };
    match sub_name {
        "version" => {
            println!("rumdl 0.1.13");
            0
        }
        "rule" => cmd_rule(&matches, sub_matches),
        "explain" => cmd_explain(&matches, sub_matches),
        "completions" => cmd_completions(&matches, sub_matches),
        "init" => cmd_init(&matches, sub_matches),
        "clean" => cmd_clean(&matches, sub_matches),
        "schema" => cmd_schema(&matches, sub_matches),
        "config" => cmd_config(&matches, sub_matches),
        "import" => cmd_import(&matches, sub_matches),
        "vscode" => cmd_vscode(&matches, sub_matches),
        "server" => cmd_server(&matches, sub_matches),
        "check" => cmd_check(&matches, sub_matches, false),
        "fmt" => cmd_check(&matches, sub_matches, true),
        _ => 2,
    }
}
