fn cmd_rule(root: &ArgMatches, sub: &ArgMatches) -> i32 {
    let color_opt = effective_color(root, Some(sub));
    let _colored = use_color(&color_opt);
    if sub.get_flag("list-categories") {
        println!("Available categories:");
        println!("  blockquote (1 rules)");
        println!("  code-block (4 rules)");
        println!("  emphasis (1 rules)");
        println!("  front-matter (1 rules)");
        println!("  heading (11 rules)");
        println!("  html (1 rules)");
        println!("  link (7 rules)");
        println!("  list (7 rules)");
        println!("  other (29 rules)");
        println!("  whitespace (5 rules)");
        return 0;
    }
    let output_format = sub.get_one::<String>("output-format").map(|s| s.as_str()).unwrap_or("text");
    let fixable_only = sub.get_flag("fixable");
    let category_filter = sub.get_one::<String>("category").cloned();
    let include_explain = sub.get_flag("explain");

    if let Some(cat) = &category_filter {
        let valid = ["blockquote","code-block","emphasis","front-matter","heading","html","link","list","other","whitespace"];
        if !valid.contains(&cat.as_str()) {
            println!("Invalid category: '{}'", cat);
            println!("Valid categories: blockquote, code-block, emphasis, front-matter, heading, html, link, list, other, whitespace");
            return 2;
        }
    }

    if let Some(rule_name) = sub.get_one::<String>("rule") {
        // Single rule
        let found = if include_explain { find_rule_explain(rule_name) } else { find_rule(rule_name) };
        // For json with explain, need explain field
        if found.is_none() {
            println!("Rule '{}' not found.", rule_name);
            return 2;
        }
        let r = found.unwrap();
        // Check filters? If single rule doesn't match filter, what happens? Probably still show? Let's assume show.
        // Actually if filter doesn't match, should it say not found? Let's just show.
        if output_format == "json" {
            let mut val = serde_json::json!({
                "code": r.code,
                "name": r.name,
                "aliases": r.aliases,
                "summary": r.summary,
                "category": r.category,
                "fix": r.fix,
                "fix_availability": r.fix_availability,
                "url": r.url,
            });
            if include_explain {
                if let Some(exp) = find_rule_explain(&r.code).and_then(|x| x.explanation) {
                    val["explanation"] = serde_json::Value::String(exp);
                }
            }
            println!("{}", serde_json::to_string_pretty(&val).unwrap());
        } else if output_format == "json-lines" {
            let mut val = serde_json::json!({
                "code": r.code,
                "name": r.name,
                "aliases": r.aliases,
                "summary": r.summary,
                "category": r.category,
                "fix": r.fix,
                "fix_availability": r.fix_availability,
                "url": r.url,
            });
            if include_explain {
                if let Some(exp) = find_rule_explain(&r.code).and_then(|x| x.explanation) {
                    val["explanation"] = serde_json::Value::String(exp);
                }
            }
