            Some(PathBuf::from(p))
        } else {
            find_config_file(None).unwrap_or(None)
        };
        if let Some(cp) = cfg_path {
            if let Ok(val) = load_config_file(&cp) {
                if let Some(dir) = val.get("global").and_then(|g| g.get("cache-dir")).and_then(|v| v.as_str()) {
                    cache_dir = PathBuf::from(dir);
                } else if let Some(dir) = val.get("global").and_then(|g| g.get("cache_dir")).and_then(|v| v.as_str()) {
                    cache_dir = PathBuf::from(dir);
                } else if let Some(dir) = val.get("cache-dir").and_then(|v| v.as_str()) {
                    // for pyproject? [tool.rumdl] has cache-dir at top? Actually global options at root for pyproject
                    cache_dir = PathBuf::from(dir);
                }
                // Also check cache = false? If cache disabled, still clean?
            }
        }
        // Also check config in cache_dir? For pyproject, global options are at top level, not under [global]
        // Our load_config_file for pyproject already extracts [tool.rumdl], so check top-level cache-dir
    }
    if !cache_dir.exists() {
        println!("No cache found at {} (nothing to clean)", cache_dir.display());
        return 0;
    }
    // Calculate size and count
    let mut total_bytes: u64 = 0;
    let mut file_count: usize = 0;
    fn walk(dir: &Path, total: &mut u64, count: &mut usize) {
        if let Ok(entries) = std::fs::read_dir(dir) {
            for e in entries.flatten() {
                let p = e.path();
                if p.is_dir() {
                    walk(&p, total, count);
                } else if let Ok(meta) = e.metadata() {
                    *total += meta.len();
                    *count += 1;
                }
            }
        }
    }
    walk(&cache_dir, &mut total_bytes, &mut file_count);
    // Remove
    let _ = std::fs::remove_dir_all(&cache_dir);
    // Format size
    let size_str = if total_bytes < 1024 {
        format!("{} B", total_bytes)
    } else if total_bytes < 1024*1024 {
        format!("{:.2} KB", total_bytes as f64 / 1024.0)
    } else {
        format!("{:.2} MB", total_bytes as f64 / (1024.0*1024.0))
    };
    println!("Cleared cache: {}", cache_dir.display());
    println!("  Removed {} across {} files", size_str, file_count);
    0
}

