                    0
                }
                Err(e) => {
                    println!("Error: Failed to write schema file: {}", e);
                    2
                }
            }
        }
        "check" => {
            let path = Path::new("rumdl.schema.json");
            if !path.exists() {
                let cwd = std::env::current_dir().unwrap_or(PathBuf::from("."));
