    }
    if !cache_dir.exists() {
        println!("No cache found at {} (nothing to clean)", cache_dir.display());
        return 0;
    }
    // Calculate size and count
    let mut total_bytes: u64 = 0;
    let mut file_count: usize = 0;
    fn walk(dir: &Path, total: &mut u64, count: &mut usize) {
        if let Ok(entries) = std::fs::read_dir(dir) {
            for e in entries.flatten() {
                let p = e.path();
                if p.is_dir() {
                    walk(&p, total, count);
                } else if let Ok(meta) = e.metadata() {
                    *total += meta.len();
                    *count += 1;
                }
            }
        }
    }
    walk(&cache_dir, &mut total_bytes, &mut file_count);
    // Remove
    let _ = std::fs::remove_dir_all(&cache_dir);
    // Format size
    let size_str = if total_bytes < 1024 {
        format!("{} B", total_bytes)
    } else if total_bytes < 1024*1024 {
        format!("{:.2} KB", total_bytes as f64 / 1024.0)
    } else {
        format!("{:.2} MB", total_bytes as f64 / (1024.0*1024.0))
    };
    println!("Cleared cache: {}", cache_dir.display());
    println!("  Removed {} across {} files", size_str, file_count);
    0
}

fn cmd_schema(root: &ArgMatches, sub: &ArgMatches) -> i32 {
    let (schema_sub, schema_matches) = match sub.subcommand() {
        Some((n, m)) => (n, m),
        None => return 2,
    };
    let schema_json = include_str!("../data/schema.json");
    match schema_sub {
        "print" => {
            print!("{}", schema_json);
            if !schema_json.ends_with('\n') {
                println!();
            }
            0
        }
        "generate" => {
            let path = Path::new("rumdl.schema.json");
            match std::fs::write(path, schema_json) {
                Ok(_) => {
                    println!("Generated JSON schema: rumdl.schema.json");
                    0
                }
                Err(e) => {
                    println!("Error: Failed to write schema file: {}", e);
                    2
                }
            }
        }
        "check" => {
            let path = Path::new("rumdl.schema.json");
            if !path.exists() {
                let cwd = std::env::current_dir().unwrap_or(PathBuf::from("."));
                println!("Error: Schema file not found: {}/rumdl.schema.json", cwd.display());
                println!("Run 'rumdl schema generate' to create it.");
                return 0;
            }
            match std::fs::read_to_string(path) {
                Ok(content) => {
                    if content == schema_json {
                        println!("Schema is up-to-date: rumdl.schema.json");
                        0
                    } else {
                        println!("Schema is out-of-date: rumdl.schema.json");
                        println!("Run 'rumdl schema generate' to update it.");
                        1
                    }
                }
                Err(e) => {
                    println!("Error: Failed to read schema file: {}", e);
                    2
                }
            }
        }
        _ => 2,
    }
}
