                out.push_str(&format!("{:<width$} {}\n", content, from_colored, width=max_len));
            }
            out.push_str("\n");
        }
        out
    } else {
        // Full padding to 176
        let mut out = String::new();
        for (sec, entries) in sections {
            let header = format!("[{}]", sec);
            // Header padded to 177? Observed header lines len 177 (including trailing space?). Let's check: "[global]" (8) padded to 177 with spaces? That's 169 spaces + newline? And our format should be "{:<176} \n"? That would be 176 + 1 space = 177? Let's replicate: header padded to 176, then " " + "\n"? Actually header lines have no "[from ...]", just padding to 177? In our earlier analysis, header len 177, value lines len 191 (176 + 15). So header is padded to 177? Or 176 + space? Let's do: format!("{:<177}\n", header) -> header (8) + 169 spaces = 177. That matches.
            // But need to check: header lines in file end with spaces then newline, no "[from ...]". Yes.
            out.push_str(&format!("{:<177}\n", header));
            for (k, v, is_default) in entries {
                let content = format!("{} = {}", k, v);
                let from = if is_default { "[from default]".to_string() } else { format!("[from {}]", source_str) };
                // Content padded to 176, then " " + from? Actually total 191 = 176 + 1 + 14? "[from default]" len 14? Let's check: "[from default]" is 14? "[" (1) + "from" (4) + " " (1) + "default" (7) + "]" (1) = 14. And with leading space, " [from default]" is 15. So 176 + 15 = 191. Good.
                // So format as "{:<176} {}\n" where second is "[from ...]" with leading space? Actually "{:<176} {}\n" with content padded to 176, then space? No, "{:<176} {}\n" would be content (padded to 176) + " " + from (14) = 176+1+14=191. Good. But our content already padded to 176, then we add " " + from.
                // For project config, "[from project config]" len? "[" (1) + "from" (4) + " " (1) + "project" (7) + " " (1) + "config" (6) + "]" (1) = 21. With leading space, 22. So total would be 176+22=198? But earlier we saw project config lines also len? Let's check: in /tmp/cfgtest, "disable = [\"MD013\"] [from project config]" with full padding? That line in full output (not --no-defaults) would be padded to 176 + " [from project config]" = 176+22=198. Let's verify by checking full output with project config.
                let from_colored = if colored { format!("\x1b[2m{}\x1b[0m", from) } else { from.clone() };
                // Need to pad content to 176 (without color), then add " " + from_colored
                out.push_str(&format!("{:<176} {}\n", content, from_colored));
            }
            out.push_str("\n");
        }
        out
    }
}

fn normalize_display_key(k: &str) -> String {
    // Display uses snake_case for respect_gitignore, but kebab for others? Let's see: in full output, global shows "respect_gitignore", not "respect-gitignore". Others are "enable", "disable", etc. (same). For rules, display uses kebab-case (e.g., "line-length", "code-blocks", etc.) except? In full output, MD001 shows "front-matter-title" (kebab), MD007 shows "start-indent", "start-indented" (kebab), etc. So only global's respect_gitignore is snake? Actually in full output, it's "respect_gitignore = true", with underscore. While JSON is "respect-gitignore" with hyphen. So display for that one key is snake.
    // For other globals, enable/disable/exclude/include/flavor are same.
    // So normalize: if k is "respect-gitignore" or "respect_gitignore", map to "respect_gitignore" for display.
    if k == "respect-gitignore" || k == "respect_gitignore" {
        "respect_gitignore".to_string()
    } else {
        k.replace('_', "-")
    }
}

fn toml_value_to_display(v: &toml::Value, key: &str) -> String {
    // Convert TOML value to display string, handling special cases:
    // - flavor: display as "Standard" (capitalized) vs JSON "standard"? In full output, "flavor = Standard" (capital S). What about other flavors? Probably "MkDocs", "MDX", etc.? Need to probe.
    // - For strings, display with quotes: e.g., style = "consistent"
    // - For arrays, display as JSON-like? e.g., disable = ["MD013"], lowercase-words = ["a", "an", ...]
    // - For booleans, "true"/"false"
    // - For integers, number
    // For flavor, capitalize?
    if key == "flavor" || key == "Flavor" {
        if let Some(s) = v.as_str() {
            // Capitalize first letter? For "standard" -> "Standard", "mkdocs" -> "MkDocs"? Let's check original: flavor display for mkdocs? Need to probe.
            // For now, match observed: "standard" -> "Standard"
            match s.to_lowercase().as_str() {
                "standard" => return "Standard".to_string(),
                "mkdocs" => return "MkDocs".to_string(),
                "mdx" => return "MDX".to_string(),
                "quarto" => return "Quarto".to_string(),
                "obsidian" => return "Obsidian".to_string(),
                _ => return s.to_string(),
            }
        }
    }
    match v {
        toml::Value::String(s) => format!("\"{}\"", s),
        toml::Value::Integer(i) => format!("{}", i),
        toml::Value::Float(f) => format!("{}", f),
        toml::Value::Boolean(b) => format!("{}", b),
        toml::Value::Array(a) => {
            let items: Vec<String> = a.iter().map(|x| toml_value_to_display(x, "")).collect();
            format!("[{}]", items.join(", "))
        }
        toml::Value::Table(t) => {
            // For inline tables like preferred-aliases = {}? Display as {}? Or { key = value }?
            if t.is_empty() {
                "{}".to_string()
            } else {
                let items: Vec<String> = t.iter().map(|(k, vv)| format!("{} = {}", k, toml_value_to_display(vv, ""))).collect();
                format!("{{ {} }}", items.join(", "))
            }
        }
        toml::Value::Datetime(d) => format!("\"{}\"", d),
    }
}

