fn cmd_config_get(root: &ArgMatches, sub: &ArgMatches, nested: &ArgMatches) -> i32 {
    let color_opt = effective_color(root, Some(sub));
    // For nested, need to check nested color? Our effective_color only checks root+sub, not nested. For config get, color could be passed as `config get --color ...` (nested) or `config --color ... get` (sub) or `--color ... config get` (root).
    // We need to handle nested color as well. For simplicity, check nested first.
    use clap::parser::ValueSource;
    let mut color_val = color_opt;
    if let Some(v) = nested.value_source("color") {
        if v == ValueSource::CommandLine {
            if let Some(c) = nested.get_one::<String>("color") {
                color_val = c.clone();
            }
        }
    }
    let colored = use_color(&color_val);
    let key = nested.get_one::<String>("key").unwrap();
    // Key must be global.key or MDxxx.key
    let parts: Vec<&str> = key.split('.').collect();
    if parts.len() != 2 {
        println!("Key must be in the form global.key or MDxxx.key");
        return 2;
    }
    let section = parts[0];
    let k = parts[1];
    // Validate section? global or MDxxx?
    let defaults = get_default_config_map();
    // Normalize section? global is lowercase, MDxxx uppercase? Accept case-insensitive? Original: `config get global.disable` works, `MD013.line-length` works, `MD013.line_length` also works (normalizes). What about `md013.line-length`? Probably case-insensitive for section? Let's assume case-insensitive for section, and kebab/snake for key.
    let mut sec_found: Option<String> = None;
    for s in defaults.keys() {
        if s.to_lowercase() == section.to_lowercase() {
            sec_found = Some(s.clone());
            break;
        }
    }
    // Also handle global keys like line-length etc. which are not in text display but are in JSON? For get, they should work? E.g., `config get global.line-length`? In JSON, global has line-length. But in text display, global doesn't show line-length. Does get support it? Let's check original.
    // For now, if section is global and key is line-length etc., handle via JSON defaults.
    if sec_found.is_none() {
        // Check if section is MDxxx not in defaults (like MD005)? Those have no config, so any key is unknown.
        // Also check global extra keys.
        if section.to_lowercase() == "global" {
            // Check extra global keys
            let extra_keys = ["line-length","line_length","fixable","unfixable","flavor","force-exclude","force_exclude","cache","cache-dir","cache_dir","output-format","output_format","respect-gitignore","respect_gitignore","enable","disable","exclude","include"];
            let mut found_extra = false;
            for ek in extra_keys {
                if ek.to_lowercase() == k.to_lowercase() || ek.replace('-', "_").to_lowercase() == k.replace('-', "_").to_lowercase() {
                    found_extra = true;
                    break;
                }
            }
            if !found_extra {
                println!("Unknown config key: {}", key);
                return 2;
            }
            // Handle extra global get via JSON
            sec_found = Some("global".to_string());
        } else {
            println!("Unknown config key: {}", key);
            return 2;
        }
    }
    let sec = sec_found.unwrap();
    // Find key in defaults (with normalization)
    let mut default_val: Option<String> = None;
    let mut display_key: String = k.to_string();
    if let Some(entries) = defaults.get(&sec) {
        for (dk, dv) in entries {
            if dk == k || dk.replace('-', "_") == k.replace('-', "_") || dk.to_lowercase() == k.to_lowercase() {
                default_val = Some(dv.clone());
                display_key = dk.clone();
                // For global respect_gitignore, display as? Original get shows "global.exclude = []"? For respect_gitignore, what does get show? Let's assume it shows as in text display (snake for respect_gitignore, kebab for others?) Need to probe.
                break;
            }
        }
    }
    // For global extra keys not in text defaults (like line-length), get default from JSON defaults
    if default_val.is_none() && sec == "global" {
        let json_defaults: HashMap<String, String> = [
            ("line-length", "80"),
            ("fixable", "[]"),
            ("unfixable", "[]"),
            ("force-exclude", "false"),
            ("cache", "true"),
        ].iter().map(|(a,b)| (a.to_string(), b.to_string())).collect();
        for (dk, dv) in json_defaults {
            if dk == k || dk.replace('-', "_") == k.replace('-', "_") {
                default_val = Some(dv);
                display_key = dk;
                break;
            }
        }
        // Also handle output-format, cache-dir? Those might not have defaults? Let's ignore.
    }

    if default_val.is_none() {
        println!("Unknown config key: {}", key);
        return 2;
    }

    // Load config to check for override
    let explicit_config = effective_config_path(root, Some(sub), Some(nested));
    let no_config = effective_no_config(root, Some(sub), Some(nested));
    let mut configured_val: Option<(String, String)> = None; // (value_str, source)
    if !no_config {
        let cfg_path = if let Some(p) = explicit_config {
            let pb = PathBuf::from(&p);
            if !pb.exists() {
                println!("Config error: Failed to read config file at {}: No such file or directory (os error 2)", p);
                return 2;
            }
            Some(pb)
        } else {
            find_config_file(None).unwrap_or(None)
        };
        if let Some(cp) = cfg_path {
            match load_config_file(&cp) {
                Ok(v) => {
                    let source = if cp.file_name().map(|n| n == "pyproject.toml").unwrap_or(false) { "pyproject.toml" } else { "project config" };
                    // Look for section.key
                    // For global, could be under [global] or top-level (pyproject)
                    if sec == "global" {
                        // Check [global] first
                        if let Some(tbl) = v.get("global").and_then(|x| x.as_table()) {
                            for (ck, cv) in tbl {
                                if ck == &display_key || ck.replace('-', "_") == display_key.replace('-', "_") || ck.to_lowercase() == display_key.to_lowercase() {
                                    let val_str = toml_value_to_display(cv, &display_key);
                                    configured_val = Some((val_str, source.to_string()));
                                    break;
                                }
                            }
                        }
                        // If not found and pyproject style, check top-level
                        if configured_val.is_none() {
                            if let Some(obj) = v.as_table() {
                                for (ck, cv) in obj {
                                    if is_global_key(ck) && (ck == &display_key || ck.replace('-', "_") == display_key.replace('-', "_")) {
                                        let val_str = toml_value_to_display(cv, &display_key);
                                        configured_val = Some((val_str, source.to_string()));
                                        break;
                                    }
                                }
                            }
                        }
                    } else {
                        if let Some(tbl) = v.get(&sec).and_then(|x| x.as_table()) {
                            for (ck, cv) in tbl {
                                if ck == &display_key || ck.replace('-', "_") == display_key.replace('-', "_") {
                                    let val_str = toml_value_to_display(cv, &display_key);
                                    configured_val = Some((val_str, source.to_string()));
                                    break;
                                }
                            }
                        }
                        // For pyproject, rules are top-level as well? After extraction, they are top-level. Good.
                    }
                }
                Err(e) => {
                    println!("Config error: {}", e);
                    return 2;
                }
            }
        }
    }

    // Display: "{sec}.{display_key} = {value} [from ...]"
    // For global, sec is "global" (lowercase). For MD, sec is as in defaults (e.g., "MD013"). What about input case? Display uses canonical (e.g., "MD013.line-length", not "md013.line-length")? Original: `config get MD013.line_length` (snake) displayed as "MD013.line-length = 100"? Yes earlier: `config get MD013.line_length` returned "MD013.line-length = 100". So it normalizes key to kebab, and section to uppercase? Let's assume.
    // For global, `config get global.disable` returns "global.disable = ..."? Yes.
    let (val_str, from) = if let Some((v, s)) = configured_val {
        (v, s)
    } else {
        (default_val.unwrap(), "default".to_string())
    };
    // Format key display: for global, use "global.{display_key}"? But display_key for respect_gitignore is snake, while JSON is kebab. For get, which? Original get for respect_gitignore? Need to probe. For now, use display_key as in defaults (snake for respect_gitignore, kebab for others).
    // However, earlier `config get MD013.line_length` (snake input) displayed as "MD013.line-length" (kebab). So display_key is kebab (from defaults). Good.
    // For global, if input is "global.respect_gitignore" vs "global.respect-gitignore", display which? Probably "global.respect_gitignore"? Or "global.respect-gitignore"? Need to probe. For now, use display_key from defaults (which is snake for that one).
    let full_key = format!("{}.{}", sec, display_key);
    let from_str = format!("[from {}]", from);
    let from_colored = if colored { format!("\x1b[2m{}\x1b[0m", from_str) } else { from_str };
    println!("{} = {} {}", full_key, val_str, from_colored);
    0
}

fn cmd_config_file(root: &ArgMatches, sub: &ArgMatches, nested: &ArgMatches) -> i32 {
    let explicit_config = effective_config_path(root, Some(sub), Some(nested));
    let no_config = effective_no_config(root, Some(sub), Some(nested));
    if no_config {
        println!("No configuration file loaded (--no-config/--isolated specified)");
        return 0;
    }
    if let Some(p) = explicit_config {
        let pb = PathBuf::from(&p);
        if !pb.exists() {
