fn is_global_key(k: &str) -> bool {
    matches!(k, "enable"|"disable"|"exclude"|"include"|"respect-gitignore"|"respect_gitignore"|"respectgitignore"|"line-length"|"line_length"|"fixable"|"unfixable"|"flavor"|"force-exclude"|"force_exclude"|"cache"|"cache-dir"|"cache_dir"|"output-format"|"output_format")
}

fn normalize_global_key(k: &str) -> String {
    match k {
        "respect_gitignore" => "respect-gitignore".to_string(),
        "line_length" => "line-length".to_string(),
        "force_exclude" => "force-exclude".to_string(),
        "cache_dir" => "cache-dir".to_string(),
        "output_format" => "output-format".to_string(),
        _ => k.to_string(),
    }
}

fn toml_to_json(v: &toml::Value) -> serde_json::Value {
    match v {
        toml::Value::String(s) => serde_json::Value::String(s.clone()),
        toml::Value::Integer(i) => serde_json::Value::Number((*i).into()),
        toml::Value::Float(f) => serde_json::Number::from_f64(*f).map(serde_json::Value::Number).unwrap_or(serde_json::Value::Null),
        toml::Value::Boolean(b) => serde_json::Value::Bool(*b),
        toml::Value::Datetime(d) => serde_json::Value::String(d.to_string()),
        toml::Value::Array(a) => serde_json::Value::Array(a.iter().map(toml_to_json).collect()),
        toml::Value::Table(t) => {
            let mut m = serde_json::Map::new();
            for (k, vv) in t {
                m.insert(k.clone(), toml_to_json(vv));
            }
            serde_json::Value::Object(m)
        }
    }
}

fn json_to_toml(v: &serde_json::Value) -> String {
    // Convert JSON object to TOML string
    // Use toml crate: convert via serde?
    // Simple: serialize JSON to TOML via toml::Value
    fn json_to_toml_val(v: &serde_json::Value) -> toml::Value {
        match v {
            serde_json::Value::Null => toml::Value::String("null".to_string()),
            serde_json::Value::Bool(b) => toml::Value::Boolean(*b),
            serde_json::Value::Number(n) => {
                if let Some(i) = n.as_i64() { toml::Value::Integer(i) }
                else if let Some(f) = n.as_f64() { toml::Value::Float(f) }
                else { toml::Value::String(n.to_string()) }
            }
            serde_json::Value::String(s) => toml::Value::String(s.clone()),
            serde_json::Value::Array(a) => toml::Value::Array(a.iter().map(json_to_toml_val).collect()),
            serde_json::Value::Object(o) => {
                let mut m = toml::map::Map::new();
                for (k, vv) in o {
                    m.insert(k.clone(), json_to_toml_val(vv));
                }
                toml::Value::Table(m)
            }
        }
    }
    let tv = json_to_toml_val(v);
    toml::to_string(&tv).unwrap_or_default()
}

