    // Display uses snake_case for respect_gitignore, but kebab for others? Let's see: in full output, global shows "respect_gitignore", not "respect-gitignore". Others are "enable", "disable", etc. (same). For rules, display uses kebab-case (e.g., "line-length", "code-blocks", etc.) except? In full output, MD001 shows "front-matter-title" (kebab), MD007 shows "start-indent", "start-indented" (kebab), etc. So only global's respect_gitignore is snake? Actually in full output, it's "respect_gitignore = true", with underscore. While JSON is "respect-gitignore" with hyphen. So display for that one key is snake.
    // For other globals, enable/disable/exclude/include/flavor are same.
    // So normalize: if k is "respect-gitignore" or "respect_gitignore", map to "respect_gitignore" for display.
    if k == "respect-gitignore" || k == "respect_gitignore" {
        "respect_gitignore".to_string()
    } else {
        k.replace('_', "-")
    }
}

fn toml_value_to_display(v: &toml::Value, key: &str) -> String {
    // Convert TOML value to display string, handling special cases:
    // - flavor: display as "Standard" (capitalized) vs JSON "standard"? In full output, "flavor = Standard" (capital S). What about other flavors? Probably "MkDocs", "MDX", etc.? Need to probe.
    // - For strings, display with quotes: e.g., style = "consistent"
    // - For arrays, display as JSON-like? e.g., disable = ["MD013"], lowercase-words = ["a", "an", ...]
    // - For booleans, "true"/"false"
    // - For integers, number
    // For flavor, capitalize?
    if key == "flavor" || key == "Flavor" {
        if let Some(s) = v.as_str() {
            // Capitalize first letter? For "standard" -> "Standard", "mkdocs" -> "MkDocs"? Let's check original: flavor display for mkdocs? Need to probe.
            // For now, match observed: "standard" -> "Standard"
            match s.to_lowercase().as_str() {
                "standard" => return "Standard".to_string(),
                "mkdocs" => return "MkDocs".to_string(),
                "mdx" => return "MDX".to_string(),
                "quarto" => return "Quarto".to_string(),
                "obsidian" => return "Obsidian".to_string(),
                _ => return s.to_string(),
            }
        }
    }
    match v {
        toml::Value::String(s) => format!("\"{}\"", s),
        toml::Value::Integer(i) => format!("{}", i),
        toml::Value::Float(f) => format!("{}", f),
        toml::Value::Boolean(b) => format!("{}", b),
        toml::Value::Array(a) => {
            let items: Vec<String> = a.iter().map(|x| toml_value_to_display(x, "")).collect();
            format!("[{}]", items.join(", "))
        }
        toml::Value::Table(t) => {
            // For inline tables like preferred-aliases = {}? Display as {}? Or { key = value }?
            if t.is_empty() {
                "{}".to_string()
            } else {
                let items: Vec<String> = t.iter().map(|(k, vv)| format!("{} = {}", k, toml_value_to_display(vv, ""))).collect();
                format!("{{ {} }}", items.join(", "))
            }
        }
        toml::Value::Datetime(d) => format!("\"{}\"", d),
    }
}

