                out.push_str(&format!("[code-block-tools.{}]\\n\\n", sub));
            }
        }
    }
    // rules: any other top-level keys starting with MD, sorted
    if let Some(obj) = v.as_object() {
        let mut rule_keys: Vec<&String> = obj.keys().filter(|k| k.starts_with("MD")).collect();
        rule_keys.sort();
        for rk in rule_keys {
            if let Some(rule_obj) = obj[*rk].as_object() {
                out.push_str(&format!("[{}]\\n", rk));
                let mut keys: Vec<&String> = rule_obj.keys().collect();
                keys.sort();
                for k in keys {
                    out.push_str(&format!("{} = {}\\n", k, json_val_to_toml_str(&rule_obj[k])));
                }
                out.push_str("\\n");
            }
        }
    }
    out
}"""
