    // For fmt --diff, shows diff + Fixed summary, exits 0, doesn't modify.
    // For check --diff, shows diff + Issues summary, exits 1, doesn't modify.
    // For check --check, shows normal issues (not diff), exits 1.
    // Need to handle these.

    // Get color
    let color_opt = {
        use clap::parser::ValueSource;
        if let Some(v) = sub.value_source("color") {
            if v == ValueSource::CommandLine {
                sub.get_one::<String>("color").unwrap().clone()
            } else if let Some(rv) = root.value_source("color") {
                if rv == ValueSource::CommandLine {
                    root.get_one::<String>("color").unwrap().clone()
                } else {
                    sub.get_one::<String>("color").unwrap().clone()
                }
            } else {
                sub.get_one::<String>("color").unwrap().clone()
            }
        } else {
            "auto".to_string()
        }
    };
    let colored_stdout = use_color(&color_opt);
    // For stderr output? If --stderr flag, diagnostics go to stderr, need to check stderr tty? For color detection when output to stderr, should check stderr tty? Original probably checks appropriate stream. For simplicity, use same colored flag for both, but when --stderr, check stderr tty for auto?
    // Actually, use_color checks stdout tty. For stderr output, should check stderr tty. Let's handle: if --stderr, use use_color_stderr.
    let to_stderr = sub.get_flag("stderr");
