                if to_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                return 2;
            }
            match load_config_file(&pb) {
                Ok(v) => { config_value = v; config_path_opt = Some(pb); }
                Err(e) => {
                    let msg = format!("Config error: {}", e);
                    if to_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                    return 2;
                }
            }
        } else {
            match find_config_file(None) {
                Ok(Some(pb)) => {
                    match load_config_file(&pb) {
                        Ok(v) => { config_value = v; config_path_opt = Some(pb); }
