            cfg_flavor = Some(v.to_string());
        }
        if let Some(v) = top_table.get("force-exclude").or_else(|| top_table.get("force_exclude")).and_then(|x| x.as_bool()) {
            cfg_force_exclude = Some(v);
        }
        if let Some(v) = top_table.get("cache").and_then(|x| x.as_bool()) {
            cfg_cache = Some(v);
        }
        if let Some(v) = top_table.get("cache-dir").or_else(|| top_table.get("cache_dir")).and_then(|x| x.as_str()) {
            cfg_cache_dir = Some(v.to_string());
        }
        if let Some(v) = top_table.get("output-format").or_else(|| top_table.get("output_format")).and_then(|x| x.as_str()) {
            cfg_output_format = Some(v.to_string());
        }
        if let Some(v) = top_table.get("line-length").or_else(|| top_table.get("line_length")).and_then(|x| x.as_integer()) {
            cfg_line_length = Some(*v as usize);
        }
    }

    // CLI enable/disable
    let cli_disable = parse_comma_list(sub.get_one::<String>("disable"));
    let cli_enable = parse_comma_list(sub.get_one::<String>("enable"));
    let cli_extend_enable = parse_comma_list(sub.get_one::<String>("extend-enable"));
    let cli_extend_disable = parse_comma_list(sub.get_one::<String>("extend-disable"));

    // Warn for unknown rules in CLI disable/enable?
    let all_codes: HashSet<String> = load_rules().iter().map(|r| r.code.clone()).collect();
    for r in &cli_disable {
        let up = normalize_rule_code(r);
        if !all_codes.contains(&up) {
            // Print warning to stderr? Original prints "[cli warning] Unknown rule in --disable: INVALID" with colors? Let's check: earlier it printed with yellow: "\x1b[33m[cli warning]\x1b[0m Unknown rule in --disable: INVALID"
            // It went to stdout or stderr? Our earlier test captured stdout+stderr together, so unknown. Likely stderr? Or stdout? Need to check.
            // For now, print to stderr if colored? Actually original printed to stdout or stderr? Let's assume stderr? But our test showed it in combined output. We'll print to stderr? Or stdout?
            // Let's probe: run with --stderr flag? Hmm.
            // For now, print to stdout? Actually warnings should go to stderr? But original's warning appeared before diagnostics, which go to stdout (unless --stderr). So warning likely goes to stderr? Or stdout?
            // We'll print to stderr for now, but need to verify.
            let warn_msg = if colored { format!("\x1b[33m[cli warning]\x1b[0m Unknown rule in --disable: {}", r) } else { format!("[cli warning] Unknown rule in --disable: {}", r) };
            eprintln!("{}", warn_msg);
        }
    }
    for r in &cli_enable {
        let up = normalize_rule_code(r);
        if !all_codes.contains(&up) {
            let warn_msg = if colored { format!("\x1b[33m[cli warning]\x1b[0m Unknown rule in --enable: {}", r) } else { format!("[cli warning] Unknown rule in --enable: {}", r) };
            eprintln!("{}", warn_msg);
        }
    }
    for r in &cli_extend_enable {
        let up = normalize_rule_code(r);
        if !all_codes.contains(&up) {
            let warn_msg = if colored { format!("\x1b[33m[cli warning]\x1b[0m Unknown rule in --extend-enable: {}", r) } else { format!("[cli warning] Unknown rule in --extend-enable: {}", r) };
            eprintln!("{}", warn_msg);
        }
    }
    for r in &cli_extend_disable {
        let up = normalize_rule_code(r);
        if !all_codes.contains(&up) {
            let warn_msg = if colored { format!("\x1b[33m[cli warning]\x1b[0m Unknown rule in --extend-disable: {}", r) } else { format!("[cli warning] Unknown rule in --extend-disable: {}", r) };
            eprintln!("{}", warn_msg);
        }
    }

    // Effective enable/disable logic:
    // If CLI --enable given, it overrides config enable (exclusive)? Or additive with extend?
    // From help: --enable "Enable only specific rules", --extend-enable "Extend the list of enabled rules (additive with config)"
    // So: if --enable given, use only those (plus extend-enable? Or extend-enable adds to CLI enable?).
    // If --enable not given but config enable non-empty, use config enable (plus extend-enable?).
    // Similarly for disable: if --disable given, use only those? Or override config disable? And extend-disable adds?
    // Let's infer: --disable overrides config disable? Or additive? Help for --disable doesn't say additive, while --extend-disable says additive. So --disable likely overrides (replaces) config disable, while --extend-disable adds.
    // Same for enable.
    // Implementation:
    let mut effective_enable: Vec<String> = vec![];
    let mut effective_disable: Vec<String> = vec![];
    let mut has_enable_filter = false;

    if !cli_enable.is_empty() {
        effective_enable = cli_enable.iter().map(|s| normalize_rule_code(s)).collect();
        has_enable_filter = true;
        // Add extend-enable
        for r in &cli_extend_enable {
            let up = normalize_rule_code(r);
            if !effective_enable.contains(&up) {
                effective_enable.push(up);
            }
        }
    } else if !cli_extend_enable.is_empty() {
        // Extend config enable
        if !cfg_enable.is_empty() {
            effective_enable = cfg_enable.iter().map(|s| normalize_rule_code(s)).collect();
            has_enable_filter = true;
            for r in &cli_extend_enable {
                let up = normalize_rule_code(r);
                if !effective_enable.contains(&up) {
                    effective_enable.push(up);
                }
            }
        } else {
            // If config has no enable (meaning all enabled), what does extend-enable do? Probably enable only those? Or no-op?
            // If config enable is empty (all enabled), extending with specific rules doesn't make sense (all already enabled). So maybe ignore?
            // For now, if config enable empty, extend-enable means enable only those? Or keep all? Let's assume keep all (no filter).
            // But to be safe, if extend-enable given and config enable empty, set enable to extend list? That would restrict to only those, which seems wrong (extend should add, not restrict).
            // Since all already enabled, extending does nothing. So leave has_enable_filter false.
        }
    } else if !cfg_enable.is_empty() {
        effective_enable = cfg_enable.iter().map(|s| normalize_rule_code(s)).collect();
        has_enable_filter = true;
    }

    if !cli_disable.is_empty() {
        effective_disable = cli_disable.iter().map(|s| normalize_rule_code(s)).collect();
        // Add extend-disable? Or extend-disable is separate? If both --disable and --extend-disable given, combine?
        for r in &cli_extend_disable {
            let up = normalize_rule_code(r);
            if !effective_disable.contains(&up) {
                effective_disable.push(up);
            }
        }
    } else {
        // Use config disable + extend-disable
        effective_disable = cfg_disable.iter().map(|s| normalize_rule_code(s)).collect();
        for r in &cli_extend_disable {
            let up = normalize_rule_code(r);
            if !effective_disable.contains(&up) {
                effective_disable.push(up);
            }
        }
    }

    // Build enabled set: all rules minus disabled, intersected with enable if present
    let mut enabled_set: HashSet<String> = all_codes.clone();
    if has_enable_filter {
        enabled_set = effective_enable.into_iter().collect();
        // Remove disabled? If both enable and disable given, disable takes precedence? Likely yes.
        for d in &effective_disable {
            enabled_set.remove(d);
        }
    } else {
        for d in &effective_disable {
            enabled_set.remove(d);
        }
    }

    // Handle per-file-ignores and per-file-flavor from config
    let mut per_file_ignores: HashMap<String, Vec<String>> = HashMap::new();
    if let Some(pfi) = config_value.get("per-file-ignores").or_else(|| config_value.get("per_file_ignores")).and_then(|v| v.as_table()) {
        for (k, v) in pfi {
            if let Some(arr) = v.as_array() {
                let rules: Vec<String> = arr.iter().filter_map(|x| x.as_str().map(|s| normalize_rule_code(s))).collect();
                per_file_ignores.insert(k.clone(), rules);
            }
        }
    }
    let mut per_file_flavor: HashMap<String, String> = HashMap::new();
    if let Some(pff) = config_value.get("per-file-flavor").or_else(|| config_value.get("per_file_flavor")).and_then(|v| v.as_table()) {
        for (k, v) in pff {
            if let Some(s) = v.as_str() {
                per_file_flavor.insert(k.clone(), s.to_lowercase());
            }
        }
    }

    // Rule configs
    let mut rule_configs: HashMap<String, toml::Value> = HashMap::new();
    if let Some(obj) = config_value.as_table() {
        for (k, v) in obj {
            if k.starts_with("MD") {
                rule_configs.insert(k.to_uppercase(), v.clone());
            }
        }
    }

    // Exclude/include
    let cli_exclude = parse_comma_list(sub.get_one::<String>("exclude"));
    let cli_include = parse_comma_list(sub.get_one::<String>("include"));
    let no_exclude = sub.get_flag("no-exclude");
    let mut effective_exclude: Vec<String> = vec![];
    let mut effective_include: Vec<String> = vec![];
    if no_exclude {
        // Disable all exclude patterns (both config and CLI? Or only config? Help says "Disable all exclude patterns" - likely disables both config and CLI exclude? But if user passes --exclude with --no-exclude, which wins? Probably --no-exclude wins (no excludes). For now, ignore all.
    } else {
        // Combine config + CLI? For exclude, CLI likely overrides? Or additive? Help doesn't say. For enable/disable, CLI overrides, extend adds. For exclude/include, no extend variant, so CLI probably adds to config? Or overrides?
        // Let's assume additive (combine).
        effective_exclude = cfg_exclude.clone();
        for e in cli_exclude {
            if !effective_exclude.contains(&e) {
                effective_exclude.push(e);
            }
        }
        effective_include = cfg_include.clone();
        for inc in cli_include {
            if !effective_include.contains(&inc) {
                effective_include.push(inc);
            }
        }
    }
    // If CLI include given and config include given, combine? Same as above.

    // Respect gitignore
    let cli_respect = sub.get_one::<String>("respect-gitignore").map(|s| s.as_str());
    // Note: --respect-gitignore without value defaults to "true" (via default_missing_value). So if flag present without value, cli_respect will be Some("true").
    // If flag not present, cli_respect will be None.
    // Config value is bool. CLI takes precedence if present.
    let mut respect_gitignore = cfg_respect_gitignore.unwrap_or(true);
    if let Some(v) = cli_respect {
        respect_gitignore = v == "true";
    }
    // Also need to check if flag was present without value? Our clap setup with default_missing_value("true") will give Some("true") when flag present without value. Good.
    // But what about --respect-gitignore=false (with =)? That gives Some("false"). Good.

    // Flavor
    let cli_flavor = sub.get_one::<String>("flavor").map(|s| s.to_lowercase());
    let mut flavor = cfg_flavor.map(|s| s.to_lowercase()).unwrap_or("standard".to_string());
    if let Some(f) = cli_flavor {
        flavor = f;
    }

    // Force exclude
    let cli_force = sub.get_flag("force-exclude");
    let mut force_exclude = cfg_force_exclude.unwrap_or(false);
    if cli_force {
        force_exclude = true;
    }

    // Cache
    let no_cache_flag = sub.get_flag("no-cache");
    let mut use_cache = cfg_cache.unwrap_or(true);
    if no_cache_flag {
        use_cache = false;
    }
    // Cache dir
    let cli_cache_dir = sub.get_one::<String>("cache-dir").cloned();
    let mut cache_dir = PathBuf::from(".rumdl_cache");
    if let Some(d) = cli_cache_dir {
        cache_dir = PathBuf::from(d);
    } else if let Ok(env) = std::env::var("RUMDL_CACHE_DIR") {
        cache_dir = PathBuf::from(env);
    } else if let Some(d) = cfg_cache_dir {
        cache_dir = PathBuf::from(d);
    }

    // Output format
    let cli_output = sub.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("text");
    let cli_output_format = sub.get_one::<String>("output-format").map(|s| s.as_str());
    let mut output_format = "text".to_string();
    // Precedence: --output-format (if explicitly given) > --output (if explicitly given and is json?) > $RUMDL_OUTPUT_FORMAT > config output-format > default text?
    // Earlier we saw --output-format takes precedence over --output when both given.
    // And --output only supports text/json (others fall back to text).
    // Need to detect if explicitly given vs default.
    use clap::parser::ValueSource;
    let output_explicit = sub.value_source("output").map(|v| v == ValueSource::CommandLine).unwrap_or(false);
    let output_format_explicit = sub.value_source("output-format").map(|v| v == ValueSource::CommandLine).unwrap_or(false);
    if output_format_explicit {
        output_format = cli_output_format.unwrap().to_string();
    } else if output_explicit {
        // --output only supports text/json? If json, use json, else text.
        if cli_output == "json" {
            output_format = "json".to_string();
        } else {
            output_format = "text".to_string();
        }
    } else if let Ok(env) = std::env::var("RUMDL_OUTPUT_FORMAT") {
        // Validate? If invalid, fall back to text? Or error? Probably fall back? Let's assume if valid value, use it, else text.
        let valid = ["text","full","concise","grouped","json","json-lines","github","gitlab","pylint","azure","sarif","junit"];
        if valid.contains(&env.as_str()) {
            output_format = env;
        } else {
            output_format = "text".to_string();
        }
    } else if let Some(cfg_fmt) = cfg_output_format {
        let valid = ["text","full","concise","grouped","json","json-lines","github","gitlab","pylint","azure","sarif","junit"];
        if valid.contains(&cfg_fmt.as_str()) {
            output_format = cfg_fmt;
        } else {
            output_format = "text".to_string();
        }
    } else {
        output_format = "text".to_string();
    }

    // Other flags
    let verbose = sub.get_flag("verbose");
    let quiet = sub.get_flag("quiet");
    let silent = sub.get_flag("silent");
    let statistics = sub.get_flag("statistics");
    let profile = sub.get_flag("profile");
    let show_full_path = sub.get_flag("show-full-path");
    let stdin_flag = sub.get_flag("stdin");
    let stdin_filename = sub.get_one::<String>("stdin-filename").cloned();
    let watch = sub.get_flag("watch");
    let fail_on = sub.get_one::<String>("fail-on").map(|s| s.as_str()).unwrap_or("any");

    // Line length default? From config global line-length or rule MD013? For now, use cfg_line_length or 80.
    let _line_length = cfg_line_length.unwrap_or(80);

    // Build CheckConfig
    let check_cfg = CheckConfig {
        enable: enabled_set.iter().cloned().collect(),
        disable: effective_disable.clone(),
        exclude: effective_exclude.clone(),
        include: effective_include.clone(),
        respect_gitignore,
        flavor: flavor.clone(),
        force_exclude,
        rule_configs: rule_configs.clone(),
        per_file_ignores: per_file_ignores.clone(),
        per_file_flavor: per_file_flavor.clone(),
        line_length: _line_length,
    };

    // Handle watch mode
    if watch {
        return run_watch(root, sub, is_fmt, &check_cfg, &enabled_set, &config_value, &color_opt, colored, to_stderr, output_format.as_str(), verbose, quiet, silent, statistics, profile, show_full_path, stdin_flag, stdin_filename.as_deref(), fail_on, use_cache, &cache_dir, effective_fix, diff_flag, check_flag);
    }

    // Handle stdin
    let paths: Vec<String> = sub.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_default();
    let use_stdin = stdin_flag || paths.iter().any(|p| p == "-");
    if use_stdin {
        return run_stdin(root, sub, is_fmt, &check_cfg, &enabled_set, &config_value, &color_opt, colored, to_stderr, output_format.as_str(), verbose, quiet, silent, statistics, profile, show_full_path, stdin_filename.as_deref(), fail_on, effective_fix, diff_flag, check_flag);
    }

    // Normal file mode
    return run_files(root, sub, is_fmt, &check_cfg, &enabled_set, &config_value, &color_opt, colored, to_stderr, output_format.as_str(), verbose, quiet, silent, statistics, profile, show_full_path, &paths, fail_on, use_cache, &cache_dir, effective_fix, diff_flag, check_flag);
}
RS"}

actions.command:
cat >> /workspace/src/main.rs <<'RS'

// ===== Check/Fmt implementation =====
#[derive(Debug, Clone)]
struct Diagnostic {
    file: String,
    line: usize,
    column: usize,
    rule: String,
    message: String,
    fixable: bool,
    fix_start: Option<usize>,
    fix_end: Option<usize>,
    fix_replacement: Option<String>,
    // For github output, need endLine/endColumn? Compute from fix or line length?
    end_line: Option<usize>,
    end_column: Option<usize>,
}

#[derive(Debug, Clone)]
struct CheckConfig {
    enable: Vec<String>,
    disable: Vec<String>,
    exclude: Vec<String>,
    include: Vec<String>,
    respect_gitignore: bool,
    flavor: String,
    force_exclude: bool,
    // Rule configs as toml::Value map
    rule_configs: HashMap<String, toml::Value>,
    per_file_ignores: HashMap<String, Vec<String>>,
    per_file_flavor: HashMap<String, String>,
    // Global line-length? Used as default for MD013? Possibly.
    line_length: usize,
}

fn parse_comma_list(s: Option<&String>) -> Vec<String> {
    if let Some(v) = s {
        v.split(',').map(|x| x.trim().to_string()).filter(|x| !x.is_empty()).collect()
    } else {
        vec![]
    }
}

fn normalize_rule_code(s: &str) -> String {
    s.trim().to_uppercase()
}

fn cmd_check(root: &ArgMatches, sub: &ArgMatches, is_fmt: bool) -> i32 {
    // Handle --fix/--diff/--check conflicts
    let fix_flag = sub.get_flag("fix");
    let diff_flag = sub.get_flag("diff");
    let check_flag = sub.get_flag("check");
    // For fmt, implicit fix unless diff/check? But explicit fix+diff/check still errors.
    // Check explicit conflicts first (same for both check and fmt)
    if fix_flag && diff_flag {
        println!("Error: --diff and --fix cannot be used together");
        println!("Use --diff to preview changes, or --fix to apply them");
        return 2;
    }
    if fix_flag && check_flag {
        println!("Error: --check and --fix cannot be used together");
        println!("Use --check to verify formatting without changes, or --fix to apply them");
        return 2;
    }
    // Determine effective fix mode
    let effective_fix = if is_fmt {
        if diff_flag || check_flag {
            false
        } else {
            true
        }
    } else {
        fix_flag
    };
    // For fmt --check, behavior is like diff + exit 1 if changes? Actually fmt --check shows diff + Fixed summary, exits 1, doesn't modify.
    // For fmt --diff, shows diff + Fixed summary, exits 0, doesn't modify.
    // For check --diff, shows diff + Issues summary, exits 1, doesn't modify.
    // For check --check, shows normal issues (not diff), exits 1.
    // Need to handle these.

    // Get color
    let color_opt = {
        use clap::parser::ValueSource;
        if let Some(v) = sub.value_source("color") {
            if v == ValueSource::CommandLine {
                sub.get_one::<String>("color").unwrap().clone()
            } else if let Some(rv) = root.value_source("color") {
                if rv == ValueSource::CommandLine {
                    root.get_one::<String>("color").unwrap().clone()
                } else {
                    sub.get_one::<String>("color").unwrap().clone()
                }
            } else {
                sub.get_one::<String>("color").unwrap().clone()
            }
        } else {
            "auto".to_string()
        }
    };
    let colored_stdout = use_color(&color_opt);
    // For stderr output? If --stderr flag, diagnostics go to stderr, need to check stderr tty? For color detection when output to stderr, should check stderr tty? Original probably checks appropriate stream. For simplicity, use same colored flag for both, but when --stderr, check stderr tty for auto?
    // Actually, use_color checks stdout tty. For stderr output, should check stderr tty. Let's handle: if --stderr, use use_color_stderr.
    let to_stderr = sub.get_flag("stderr");
    let colored = if to_stderr { use_color_stderr(&color_opt) } else { colored_stdout };

    // Get config path and no-config
    let explicit_config = {
        use clap::parser::ValueSource;
        let mut explicit: Option<String> = None;
        if let Some(v) = sub.value_source("config") {
            if v == ValueSource::CommandLine {
                explicit = sub.get_one::<String>("config").cloned();
            }
        }
        if explicit.is_none() {
            if let Some(v) = root.value_source("config") {
                if v == ValueSource::CommandLine {
                    explicit = root.get_one::<String>("config").cloned();
                }
            }
        }
        explicit
    };
    let no_config = sub.get_flag("no-config") || sub.get_flag("isolated") || root.get_flag("no-config") || root.get_flag("isolated");

    // Load config file
    let mut config_value = toml::Value::Table(toml::map::Map::new());
    let mut config_path_opt: Option<PathBuf> = None;
    if !no_config {
        if let Some(ref p) = explicit_config {
            let pb = PathBuf::from(p);
            if !pb.exists() {
                let msg = format!("Config error: Failed to read config file at {}: No such file or directory (os error 2)", p);
                if to_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                return 2;
            }
            match load_config_file(&pb) {
                Ok(v) => { config_value = v; config_path_opt = Some(pb); }
                Err(e) => {
                    let msg = format!("Config error: {}", e);
                    if to_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                    return 2;
                }
            }
        } else {
            match find_config_file(None) {
                Ok(Some(pb)) => {
                    match load_config_file(&pb) {
                        Ok(v) => { config_value = v; config_path_opt = Some(pb); }
                        Err(e) => {
                            let msg = format!("Config error: {}", e);
                            if to_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                            return 2;
                        }
                    }
                }
                Ok(None) => {}
                Err(e) => {
                    let msg = format!("Config error: {}", e);
                    if to_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                    return 2;
                }
            }
        }
    }

    // Parse enable/disable from CLI and config
    // Config enable/disable: under [global] or top-level (pyproject)?
    let mut cfg_enable: Vec<String> = vec![];
    let mut cfg_disable: Vec<String> = vec![];
    let mut cfg_exclude: Vec<String> = vec![];
    let mut cfg_include: Vec<String> = vec![];
    let mut cfg_respect_gitignore: Option<bool> = None;
    let mut cfg_flavor: Option<String> = None;
    let mut cfg_force_exclude: Option<bool> = None;
    let mut cfg_cache: Option<bool> = None;
    let mut cfg_cache_dir: Option<String> = None;
    let mut cfg_output_format: Option<String> = None;
    let mut cfg_line_length: Option<usize> = None;

    // Helper to extract from global table or top-level
    let global_table = config_value.get("global").and_then(|v| v.as_table()).cloned();
    let top_table = config_value.as_table().cloned().unwrap_or_default();

    // Get enable
    if let Some(g) = &global_table {
        if let Some(v) = g.get("enable").and_then(|x| x.as_array()) {
            cfg_enable = v.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
        }
        if let Some(v) = g.get("disable").and_then(|x| x.as_array()) {
            cfg_disable = v.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
        }
        if let Some(v) = g.get("exclude").and_then(|x| x.as_array()) {
            cfg_exclude = v.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
        }
        if let Some(v) = g.get("include").and_then(|x| x.as_array()) {
            cfg_include = v.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
        }
        if let Some(v) = g.get("respect-gitignore").or_else(|| g.get("respect_gitignore")).and_then(|x| x.as_bool()) {
            cfg_respect_gitignore = Some(v);
        }
        if let Some(v) = g.get("flavor").and_then(|x| x.as_str()) {
