            if trimmed_start.starts_with("```") || trimmed_start.starts_with("~~~") {
                let ch = trimmed_start.chars().next().unwrap();
                // Count fence length
                let mut len = 0;
                for c in trimmed_start.chars() {
                    if c == ch { len += 1; } else { break; }
                }
                if len >= 3 {
