                                fence_lines[idx] = true;
                                fence_char[idx] = Some(ch);
                                in_fence = None;
                                fence_start_idx = None;
                                continue;
                            }
                        }
                        // If inside fence but not closing, it's code content
                        is_code[idx] = true;
                        continue;
                    } else {
                        // Opening
                        // For ```, info string can contain anything except `? Actually ``` info cannot contain `, but we ignore.
                        is_code[idx] = true;
                        fence_lines[idx] = true;
                        fence_char[idx] = Some(ch);
                        in_fence = Some((ch, len));
                        fence_start_idx = Some(idx);
                        continue;
                    }
                }
            }
        }
        if in_fence.is_some() {
            is_code[idx] = true;
        } else {
            // Check for indented code blocks: line starts with 4+ spaces (or tab) and not blank, and not list item? Simplified: 4+ spaces indent.
