fn simple_hash(s: &str) -> String {
    // Simple hash to hex (not cryptographic, just for cache file name)
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    let mut hasher = DefaultHasher::new();
    s.hash(&mut hasher);
    format!("{:016x}{:016x}", hasher.finish(), hasher.finish().wrapping_add(1))
}

fn compute_exit_code(diags: &[Diagnostic], fail_on: &str, is_fmt: bool, effective_fix: bool, diff_flag: bool, check_flag: bool, fixed: usize, total: usize) -> i32 {
    // For fmt (without --check/--diff), always exit 0 (even with issues). For fmt --check, exit 1 if changes would be made (i.e., if fixable>0? Or if any issues? Original fmt --check with fixable issues exited 1. What about fmt --check with only unfixable? Would it exit 0 or 1? Since no changes would be made (unfixable can't be fixed), maybe exit 0? Need to probe. For now, assume fmt --check exits 1 if any fixable issues, else 0.
    // For fmt --diff, always exit 0 (even with issues). Earlier fmt --diff exited 0 with fixable issues. Good.
    // For check: exit based on fail_on and issues.
    // fail_on: any (default) exits 1 on any violation, warning on warning+error, error only on errors, never always 0.
    // Since all our diagnostics are warnings (severity warning), fail_on any/warning => exit 1 if any issues, error => exit 0 (since no errors), never => 0.
    // But what about --fix with all fixed? Then diags after fix? For check --fix with all fixed, original exited 0 and showed Fixed summary, not Issues. Our current run_files doesn't handle fix yet (always shows Issues). Need to handle fix mode separately.
    // For now, for non-fix modes:
    if is_fmt {
        if diff_flag {
            return 0;
        }
        if check_flag {
            // fmt --check: exit 1 if changes would be made (i.e., if any fixable issues)
            let fixable = diags.iter().filter(|d| d.fixable).count();
            if fixable > 0 { return 1; } else { return 0; }
        }
        // Normal fmt (fix mode): always 0. But our current run_files doesn't actually fix yet, so it would show Issues but exit 0? Original fmt with unfixable shows Issues and exits 0. Good. With fixable, it shows Fixed and exits 0. Our stub shows Issues and would exit 0 (since is_fmt). Good for now.
        return 0;
    } else {
        // check
        if diff_flag || check_flag {
            // check --diff and --check both exit 1 if any issues? Earlier check --diff with fixable exited 1, check --check with fixable exited 1. What about unfixable? Both exited 1 as well (since they show Issues). Good. So same as normal check.
        }
        if effective_fix {
            // check --fix: exit 1 if unfixable remain, else 0. Since we don't handle fix yet, treat as normal check for now.
        }
        match fail_on {
            "never" => 0,
            "error" => 0, // Since all warnings, no errors
            "warning" | "any" => if diags.is_empty() { 0 } else { 1 },
            _ => if diags.is_empty() { 0 } else { 1 },
        }
    }
}

fn format_json(diags: &[Diagnostic], show_full_path: bool) -> String {
    // Format as JSON array with file, line, column, rule, message, severity, fixable, fix (if fixable with range)
    let mut arr = Vec::new();
    for d in diags {
        let file_disp = if show_full_path {
            if Path::new(&d.file).is_absolute() { d.file.clone() } else { std::env::current_dir().map(|cwd| cwd.join(&d.file).display().to_string()).unwrap_or(d.file.clone()) }
        } else {
            d.file.clone()
        };
        let mut obj = serde_json::json!({
            "file": file_disp,
            "line": d.line,
            "column": d.column,
            "rule": d.rule,
            "message": d.message,
            "severity": "warning",
            "fixable": d.fixable,
        });
        if d.fixable {
            if let (Some(s), Some(e), Some(r)) = (d.fix_start, d.fix_end, &d.fix_replacement) {
                obj["fix"] = serde_json::json!({
                    "range": { "start": s, "end": e },
                    "replacement": r
                });
            }
        }
        arr.push(obj);
    }
    serde_json::to_string_pretty(&serde_json::Value::Array(arr)).unwrap() + "\n"
}

fn format_json_lines(diags: &[Diagnostic], show_full_path: bool) -> String {
    let mut out = String::new();
    for d in diags {
        let file_disp = if show_full_path {
            if Path::new(&d.file).is_absolute() { d.file.clone() } else { std::env::current_dir().map(|cwd| cwd.join(&d.file).display().to_string()).unwrap_or(d.file.clone()) }
        } else {
            d.file.clone()
        };
        let obj = serde_json::json!({
            "file": file_disp,
            "line": d.line,
            "column": d.column,
            "rule": d.rule,
            "message": d.message,
            "severity": "warning",
            "fixable": d.fixable,
        });
        out.push_str(&serde_json::to_string(&obj).unwrap());
        out.push_str("\n");
    }
    out
}

fn format_statistics(diags: &[Diagnostic], colored: bool) -> String {
    use std::collections::HashMap;
    let mut counts: HashMap<String, (usize, usize)> = HashMap::new(); // rule -> (total, fixable)
    for d in diags {
        let e = counts.entry(d.rule.clone()).or_insert((0,0));
        e.0 += 1;
        if d.fixable { e.1 += 1; }
    }
    let mut sorted: Vec<(String, usize, usize)> = counts.into_iter().map(|(k,(t,f))| (k,t,f)).collect();
    sorted.sort_by(|a,b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    let mut out = String::new();
    out.push_str("\nRule Violation Statistics:\n");
    out.push_str("Rule     Violations   Fixable  Percentage\n");
    out.push_str("--------------------------------------------------\n");
    let total = diags.len();
    for (rule, count, fixable) in sorted {
        let pct = if total > 0 { count as f64 / total as f64 * 100.0 } else { 0.0 };
        out.push_str(&format!("{:<8} {:<12} {:<8} {:>5.1}%\n", rule, count, fixable, pct));
    }
    out.push_str("--------------------------------------------------\n");
    let total_fixable = diags.iter().filter(|d| d.fixable).count();
    out.push_str(&format!("{:<8} {:<12} {:<8} {:>5.1}%\n", "Total", total, total_fixable, 100.0));
    out
}
