        // Colors: file in blue underline? Earlier: file \x1b[4;34m, line/col \x1b[36m, rule \x1b[33m, [*] \x1b[32m
        // Format: "file:line:col: [RULE] message [*]"
        if colored {
            out.push_str(&format!("\x1b[4;34m{}\x1b[0m:\x1b[36m{}\x1b[0m:\x1b[36m{}\x1b[0m: \x1b[33m[{}]\x1b[0m {}", file_disp, d.line, d.column, d.rule, d.message));
