fn format_diagnostics_fixed(diags: &[Diagnostic], show_full_path: bool, colored: bool) -> String {
    let mut out = String::new();
    for d in diags {
        let file_disp = if show_full_path {
            if Path::new(&d.file).is_absolute() {
                d.file.clone()
            } else {
                std::env::current_dir().map(|cwd| cwd.join(&d.file).display().to_string()).unwrap_or(d.file.clone())
            }
        } else {
            d.file.clone()
        };
        if d.fixable {
            if colored {
                out.push_str(&format!("\x1b[4;34m{}\x1b[0m:\x1b[36m{}\x1b[0m:\x1b[36m{}\x1b[0m: \x1b[33m[{}]\x1b[0m {} \x1b[32m[fixed]\x1b[0m\n", file_disp, d.line, d.column, d.rule, d.message));
            } else {
                out.push_str(&format!("{}:{}:{}: [{}] {} [fixed]\n", file_disp, d.line, d.column, d.rule, d.message));
            }
        } else {
            if colored {
                out.push_str(&format!("\x1b[4;34m{}\x1b[0m:\x1b[36m{}\x1b[0m:\x1b[36m{}\x1b[0m: \x1b[33m[{}]\x1b[0m {}\n", file_disp, d.line, d.column, d.rule, d.message));
            } else {
                out.push_str(&format!("{}:{}:{}: [{}] {}\n", file_disp, d.line, d.column, d.rule, d.message));
            }
        }
    }
    out
}

