    // Concise: same as text but without [*] markers? Earlier concise output for test.md showed diagnostics without [*], plus Issues summary. Good.
    let mut out = String::new();
    for d in diags {
        let file_disp = if show_full_path {
            if Path::new(&d.file).is_absolute() { d.file.clone() } else { std::env::current_dir().map(|cwd| cwd.join(&d.file).display().to_string()).unwrap_or(d.file.clone()) }
        } else { d.file.clone() };
        if colored {
            out.push_str(&format!("\x1b[4;34m{}\x1b[0m:\x1b[36m{}\x1b[0m:\x1b[36m{}\x1b[0m: \x1b[33m[{}]\x1b[0m {}\n", file_disp, d.line, d.column, d.rule, d.message));
        } else {
            out.push_str(&format!("{}:{}:{}: [{}] {}\n", file_disp, d.line, d.column, d.rule, d.message));
        }
    }
    out
}

fn format_grouped(diags: &[Diagnostic], show_full_path: bool, colored: bool) -> String {
    // Grouped: group by file, then by rule? Earlier grouped output:
    // /tmp/t1/test.md:
    //   MD004:
    //     5:1 List marker ... (fixable)
    //   MD009:
    //     2:31 ... (fixable)
    // ...
    // Need to replicate exactly, including order (rules sorted? Files sorted?).
    // From earlier: file "/tmp/t1/test.md:", then rules in order MD004, MD009, MD022, MD026, MD032 (alphabetical? MD004, MD009, MD022, MD026, MD032 - yes alphabetical). Within each rule, sorted by line? For MD022 (2 issues: 1:1 and 3:1), order was 1:1 then 3:1 (sorted). Good.
    // Format: "{file}:\n  {rule}:\n    {line}:{col} {message} (fixable|...)?" What about non-fixable? Probably without "(fixable)"? Or with different marker? Need to probe grouped with non-fixable (e.g., MD041). For now, assume fixable shows " (fixable)", non-fixable shows nothing? Or "(not fixable)"? Let's check original grouped with mixed (fixable + unfixable).
    // For now, implement as: if fixable, append " (fixable)", else nothing? Or maybe " (not fixable)"? Need to probe.
    use std::collections::BTreeMap;
    let mut by_file: BTreeMap<String, Vec<&Diagnostic>> = BTreeMap::new();
    for d in diags {
        let file_disp = if show_full_path {
            if Path::new(&d.file).is_absolute() { d.file.clone() } else { std::env::current_dir().map(|cwd| cwd.join(&d.file).display().to_string()).unwrap_or(d.file.clone()) }
        } else { d.file.clone() };
        by_file.entry(file_disp).or_default().push(d);
    }
    let mut out = String::new();
    for (file, mut ds) in by_file {
        // Group by rule
        let mut by_rule: BTreeMap<String, Vec<&&Diagnostic>> = BTreeMap::new();
        for d in &ds {
            by_rule.entry(d.rule.clone()).or_default().push(d);
        }
        out.push_str(&format!("{}:\n", file));
        for (rule, mut rds) in by_rule {
            out.push_str(&format!("  {}:\n", rule));
            rds.sort_by(|a,b| a.line.cmp(&b.line).then(a.column.cmp(&b.column)));
            for d in rds {
                if d.fixable {
                    out.push_str(&format!("    {}:{} {} (fixable)\n", d.line, d.column, d.message));
                } else {
                    out.push_str(&format!("    {}:{} {}\n", d.line, d.column, d.message));
                }
            }
        }
    }
    out
}

