fn format_gitlab(diags: &[Diagnostic], show_full_path: bool) -> String {
    // Gitlab Code Quality format: JSON array with description, check_name, fingerprint, severity, location
    let mut arr = Vec::new();
    for d in diags {
        let file_disp = if show_full_path {
            if Path::new(&d.file).is_absolute() { d.file.clone() } else { std::env::current_dir().map(|cwd| cwd.join(&d.file).display().to_string()).unwrap_or(d.file.clone()) }
        } else { d.file.clone() };
        let fingerprint = format!("{}-{}-{}-{}", file_disp, d.line, d.column, d.rule);
        let obj = serde_json::json!({
            "description": d.message,
            "check_name": d.rule,
            "fingerprint": fingerprint,
            "severity": "minor",
            "location": {
                "path": file_disp,
                "lines": { "begin": d.line }
            }
        });
        arr.push(obj);
    }
    serde_json::to_string_pretty(&serde_json::Value::Array(arr)).unwrap() + "\n"
}

