fn format_sarif(diags: &[Diagnostic], show_full_path: bool) -> String {
    // SARIF: JSON object with $schema, version, runs[0].tool.driver (name, version, informationUri, rules[]) and results[]
    // Rules: unique rules in diags, each with id, name, shortDescription, fullDescription
    // Results: each diag with ruleId, level warning, message.text, locations[0].physicalLocation.artifactLocation.uri and region.startLine/startColumn
    use std::collections::BTreeSet;
    let mut rules_set = BTreeSet::new();
    for d in diags {
        rules_set.insert(d.rule.clone());
    }
    let mut rules_arr = Vec::new();
    for r in &rules_set {
        rules_arr.push(serde_json::json!({
            "id": r,
            "name": r,
            "shortDescription": { "text": format!("Markdown rule {}", r) },
            "fullDescription": { "text": format!("Markdown linting rule {}", r) }
        }));
    }
    let mut results = Vec::new();
    for d in diags {
        let file_disp = if show_full_path {
            if Path::new(&d.file).is_absolute() { d.file.clone() } else { std::env::current_dir().map(|cwd| cwd.join(&d.file).display().to_string()).unwrap_or(d.file.clone()) }
        } else { d.file.clone() };
        results.push(serde_json::json!({
            "ruleId": d.rule,
            "level": "warning",
            "message": { "text": d.message },
            "locations": [{
                "physicalLocation": {
                    "artifactLocation": { "uri": file_disp },
                    "region": { "startLine": d.line, "startColumn": d.column }
                }
            }]
        }));
    }
    let sarif = serde_json::json!({
        "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
        "version": "2.1.0",
        "runs": [{
            "tool": {
                "driver": {
                    "name": "rumdl",
                    "version": "0.1.13",
                    "informationUri": "https://github.com/rvben/rumdl",
                    "rules": rules_arr
                }
            },
            "results": results
        }]
    });
    serde_json::to_string_pretty(&sarif).unwrap() + "\n"
}

